# frozen_string_literal: true

require_relative "../../plaid"

module Plaid
  module Types
    # Configures which Home Lending VOA report format is retrieved. Omit when retrieving a report generated by
    # `/cra/report/create` or `/link/token/create`; the report is returned with the options it was generated with.
    class CraReportGetHomeLendingVoaOptions < Internal::Types::Model
      field :report_format, -> { Plaid::Types::CraHomeLendingVoaReportFormat }, optional: true, nullable: false
    end
  end
end
